export type ToneName =
  | 'attack'
  | 'dash'
  | 'hit'
  | 'hurt'
  | 'freeze'
  | 'warning'
  | 'warning-melee'
  | 'warning-ranged'
  | 'warning-boss'
  | 'dash-ready'
  | 'footstep'
  | 'shot'
  | 'death'
  | 'room-start'
  | 'room-clear'
  | 'reward'
  | 'victory'

const TONES: Record<
  ToneName,
  { frequency: number; duration: number; type: OscillatorType }
> = {
  attack: { frequency: 180, duration: 0.08, type: 'sawtooth' },
  dash: { frequency: 360, duration: 0.11, type: 'triangle' },
  hit: { frequency: 95, duration: 0.1, type: 'square' },
  hurt: { frequency: 70, duration: 0.18, type: 'sawtooth' },
  freeze: { frequency: 520, duration: 0.12, type: 'sine' },
  warning: { frequency: 440, duration: 0.16, type: 'square' },
  'warning-melee': { frequency: 390, duration: 0.12, type: 'square' },
  'warning-ranged': { frequency: 610, duration: 0.18, type: 'triangle' },
  'warning-boss': { frequency: 165, duration: 0.3, type: 'sawtooth' },
  'dash-ready': { frequency: 740, duration: 0.09, type: 'sine' },
  footstep: { frequency: 105, duration: 0.045, type: 'triangle' },
  shot: { frequency: 260, duration: 0.09, type: 'triangle' },
  death: { frequency: 110, duration: 0.24, type: 'sawtooth' },
  'room-start': { frequency: 540, duration: 0.24, type: 'triangle' },
  'room-clear': { frequency: 740, duration: 0.34, type: 'triangle' },
  reward: { frequency: 660, duration: 0.22, type: 'triangle' },
  victory: { frequency: 880, duration: 0.45, type: 'triangle' },
}

interface SampleVariant {
  readonly path: string
  readonly gain: number
  readonly playbackRate?: number
}

const SAMPLE_VARIANTS: Record<ToneName, readonly SampleVariant[]> = {
  attack: [
    { path: 'sfx/sword-swing-1.ogg', gain: 0.58 },
    { path: 'sfx/sword-swing-2.ogg', gain: 0.58 },
  ],
  dash: [{ path: 'sfx/draw-weapon.ogg', gain: 0.44, playbackRate: 1.3 }],
  hit: [
    { path: 'sfx/hit-light.ogg', gain: 0.5 },
    { path: 'sfx/armor-hit.ogg', gain: 0.42 },
  ],
  hurt: [{ path: 'sfx/hit-heavy.ogg', gain: 0.62, playbackRate: 0.88 }],
  freeze: [{ path: 'sfx/ui-select.ogg', gain: 0.32, playbackRate: 1.32 }],
  warning: [{ path: 'sfx/ui-error.ogg', gain: 0.34, playbackRate: 1.08 }],
  'warning-melee': [
    { path: 'sfx/ui-error.ogg', gain: 0.32, playbackRate: 0.96 },
  ],
  'warning-ranged': [
    { path: 'sfx/ui-error.ogg', gain: 0.3, playbackRate: 1.34 },
  ],
  'warning-boss': [
    { path: 'sfx/hit-heavy.ogg', gain: 0.38, playbackRate: 0.68 },
  ],
  'dash-ready': [{ path: 'sfx/ui-select.ogg', gain: 0.24, playbackRate: 1.48 }],
  footstep: [
    { path: 'sfx/footstep-1.ogg', gain: 0.18 },
    { path: 'sfx/footstep-2.ogg', gain: 0.18 },
  ],
  shot: [{ path: 'sfx/draw-weapon.ogg', gain: 0.4, playbackRate: 1.55 }],
  death: [{ path: 'sfx/hit-heavy.ogg', gain: 0.56, playbackRate: 0.72 }],
  'room-start': [{ path: 'sfx/ui-select.ogg', gain: 0.34, playbackRate: 0.92 }],
  'room-clear': [
    { path: 'sfx/ui-confirm.ogg', gain: 0.44, playbackRate: 1.08 },
  ],
  reward: [{ path: 'sfx/ui-confirm.ogg', gain: 0.4 }],
  victory: [{ path: 'sfx/ui-confirm.ogg', gain: 0.5, playbackRate: 0.9 }],
}

const MUSIC_PATH = 'music/dungeon-loop-1.ogg'
const WARNING_COOLDOWN_SECONDS = 0.14

function clampUnit(value: number): number {
  return Math.max(0, Math.min(1, value))
}

function audioAssetUrl(path: string): string {
  return `${import.meta.env.BASE_URL}assets/audio/${path}`
}

export class AudioEngine {
  private context: AudioContext | null = null
  private master: GainNode | null = null
  private volume = 0.55
  private contextCreationFailed = false
  private preloadPromise: Promise<void> | null = null
  private readonly buffers = new Map<string, AudioBuffer>()
  private readonly variationIndices = new Map<ToneName, number>()
  private readonly lastPlayedAt = new Map<ToneName, number>()
  private musicRequested = false
  private musicPlayback: {
    source: AudioBufferSourceNode
    gain: GainNode
  } | null = null
  private resumeRetryArmed = false
  private readonly retryUnlock = () => {
    this.disarmResumeRetry()
    void this.unlock()
  }

  async unlock(signal?: AbortSignal): Promise<void> {
    const context = this.ensureContext()
    if (!context) return

    const resume =
      context.state === 'suspended'
        ? context.resume().catch(() => undefined)
        : Promise.resolve()
    await Promise.all([resume, this.preload(signal)])
    if (context.state === 'running') {
      this.disarmResumeRetry()
      this.startMusicIfReady()
    } else {
      this.armResumeRetry()
    }
  }

  private ensureContext(): AudioContext | null {
    if (this.context) return this.context
    if (this.contextCreationFailed) return null

    const primedContext =
      typeof window === 'undefined'
        ? undefined
        : window.__BODA_PRIMED_AUDIO_CONTEXT__
    if (primedContext && typeof window !== 'undefined') {
      window.__BODA_PRIMED_AUDIO_CONTEXT__ = undefined
    }
    if (primedContext && primedContext.state !== 'closed') {
      try {
        this.context = primedContext
        this.master = primedContext.createGain()
        this.master.gain.value = this.volume
        this.master.connect(primedContext.destination)
        return primedContext
      } catch {
        this.context = null
        this.master = null
      }
    }

    const AudioContextConstructor = globalThis.AudioContext
    if (typeof AudioContextConstructor !== 'function') {
      this.contextCreationFailed = true
      return null
    }

    try {
      this.context = new AudioContextConstructor()
      this.master = this.context.createGain()
      this.master.gain.value = this.volume
      this.master.connect(this.context.destination)
      return this.context
    } catch {
      this.context = null
      this.master = null
      this.contextCreationFailed = true
      return null
    }
  }

  private preload(signal?: AbortSignal): Promise<void> {
    if (this.preloadPromise) return this.preloadPromise
    const context = this.context
    if (!context || typeof fetch !== 'function') {
      this.preloadPromise = Promise.resolve()
      return this.preloadPromise
    }

    const paths = new Set([
      MUSIC_PATH,
      ...Object.values(SAMPLE_VARIANTS).flatMap((variants) =>
        variants.map((variant) => variant.path),
      ),
    ])
    const promise = Promise.all(
      [...paths].map(async (path) => {
        try {
          const response = signal
            ? await fetch(audioAssetUrl(path), { signal })
            : await fetch(audioAssetUrl(path))
          if (!response.ok) return
          const encoded = await response.arrayBuffer()
          const buffer = await context.decodeAudioData(encoded)
          this.buffers.set(path, buffer)
        } catch {
          // Individual files fall back to the existing synthesized cue.
        }
      }),
    ).then(() => undefined)
    this.preloadPromise = promise
    // A cancelled boot must not memoize a half-loaded sample set, or audio
    // would stay degraded for the rest of the session with no way to retry.
    void promise.then(() => {
      if (signal?.aborted && this.preloadPromise === promise) {
        this.preloadPromise = null
      }
    })
    return promise
  }

  /**
   * Silences the graph while the tab is hidden. Suspending the context rather
   * than muting also stops the music loop from consuming a decode thread in a
   * background tab.
   */
  suspendForHiddenTab(): void {
    const context = this.context
    if (!context || context.state !== 'running') return
    void context.suspend().catch(() => undefined)
  }

  /** Resumes after suspendForHiddenTab. Safe to call when already running. */
  resumeFromHiddenTab(): void {
    const context = this.context
    if (!context || context.state !== 'suspended') return
    void context
      .resume()
      .then(() => this.startMusicIfReady())
      .catch(() => undefined)
  }

  setVolume(value: number): void {
    this.volume = clampUnit(value)
    this.master?.gain.setTargetAtTime(
      this.volume,
      this.context?.currentTime ?? 0,
      0.02,
    )
  }

  play(name: ToneName, pan = 0): void {
    const context = this.context
    if (context && context.state !== 'running') this.armResumeRetry()
    if (
      !context ||
      !this.master ||
      context.state !== 'running' ||
      this.volume === 0
    ) {
      return
    }

    const now = context.currentTime
    const lastPlayedAt = this.lastPlayedAt.get(name)
    if (
      name === 'warning' &&
      lastPlayedAt !== undefined &&
      now - lastPlayedAt < WARNING_COOLDOWN_SECONDS
    ) {
      return
    }

    const played = this.playSample(name, pan) || this.playSynthesized(name, pan)
    if (played) this.lastPlayedAt.set(name, now)
  }

  private playSample(name: ToneName, pan: number): boolean {
    const context = this.context
    const master = this.master
    if (!context || !master) return false

    const variants = SAMPLE_VARIANTS[name]
    const startIndex = this.variationIndices.get(name) ?? 0
    this.variationIndices.set(name, (startIndex + 1) % variants.length)

    for (let offset = 0; offset < variants.length; offset += 1) {
      const variant = variants[(startIndex + offset) % variants.length]
      const buffer = this.buffers.get(variant.path)
      if (!buffer) continue

      let source: AudioBufferSourceNode | null = null
      let gain: GainNode | null = null
      let panner: StereoPannerNode | null = null
      try {
        source = context.createBufferSource()
        gain = context.createGain()
        source.buffer = buffer
        source.playbackRate.setValueAtTime(
          variant.playbackRate ?? 1,
          context.currentTime,
        )
        gain.gain.setValueAtTime(variant.gain, context.currentTime)
        source.connect(gain)
        panner = this.connectPanned(gain, pan)
        source.onended = () => {
          source?.disconnect()
          gain?.disconnect()
          panner?.disconnect()
        }
        source.start(context.currentTime)
        return true
      } catch {
        source?.disconnect()
        gain?.disconnect()
        panner?.disconnect()
      }
    }

    return false
  }

  private playSynthesized(name: ToneName, pan: number): boolean {
    const context = this.context
    if (!context || !this.master) return false

    const tone = TONES[name]
    const now = context.currentTime
    let oscillator: OscillatorNode | null = null
    let gain: GainNode | null = null
    let panner: StereoPannerNode | null = null
    try {
      oscillator = context.createOscillator()
      gain = context.createGain()
      oscillator.type = tone.type
      oscillator.frequency.setValueAtTime(tone.frequency, now)
      oscillator.frequency.exponentialRampToValueAtTime(
        Math.max(45, tone.frequency * 0.55),
        now + tone.duration,
      )
      gain.gain.setValueAtTime(0.0001, now)
      gain.gain.exponentialRampToValueAtTime(0.18, now + 0.008)
      gain.gain.exponentialRampToValueAtTime(0.0001, now + tone.duration)
      oscillator.connect(gain)
      panner = this.connectPanned(gain, pan)
      oscillator.onended = () => {
        oscillator?.disconnect()
        gain?.disconnect()
        panner?.disconnect()
      }
      oscillator.start(now)
      oscillator.stop(now + tone.duration + 0.02)
      return true
    } catch {
      oscillator?.disconnect()
      gain?.disconnect()
      panner?.disconnect()
      return false
    }
  }

  private connectPanned(node: AudioNode, pan: number): StereoPannerNode | null {
    const context = this.context
    const master = this.master
    if (!context || !master) return null

    try {
      const panner = context.createStereoPanner()
      panner.pan.setValueAtTime(
        Math.max(-1, Math.min(1, pan)),
        context.currentTime,
      )
      node.connect(panner)
      panner.connect(master)
      return panner
    } catch {
      node.connect(master)
      return null
    }
  }

  playDirectional(name: ToneName, horizontalDirection: number): void {
    this.play(name, horizontalDirection)
  }

  private armResumeRetry(): void {
    if (this.resumeRetryArmed || typeof window === 'undefined') return
    this.resumeRetryArmed = true
    window.addEventListener('pointerdown', this.retryUnlock, {
      capture: true,
      once: true,
    })
    window.addEventListener('keydown', this.retryUnlock, {
      capture: true,
      once: true,
    })
  }

  private disarmResumeRetry(): void {
    if (!this.resumeRetryArmed || typeof window === 'undefined') return
    this.resumeRetryArmed = false
    window.removeEventListener('pointerdown', this.retryUnlock, true)
    window.removeEventListener('keydown', this.retryUnlock, true)
  }

  startMusic(): void {
    this.musicRequested = true
    if (!this.context) return
    void this.preload().then(() => this.startMusicIfReady())
  }

  private startMusicIfReady(): void {
    const context = this.context
    const master = this.master
    const buffer = this.buffers.get(MUSIC_PATH)
    if (
      !this.musicRequested ||
      this.musicPlayback ||
      !context ||
      !master ||
      !buffer ||
      context.state !== 'running'
    ) {
      return
    }

    let source: AudioBufferSourceNode | null = null
    let gain: GainNode | null = null
    try {
      source = context.createBufferSource()
      gain = context.createGain()
      source.buffer = buffer
      source.loop = true
      gain.gain.setValueAtTime(0.0001, context.currentTime)
      gain.gain.exponentialRampToValueAtTime(0.24, context.currentTime + 0.35)
      source.connect(gain)
      gain.connect(master)
      const playback = { source, gain }
      this.musicPlayback = playback
      source.onended = () => {
        source?.disconnect()
        gain?.disconnect()
        if (this.musicPlayback === playback) this.musicPlayback = null
      }
      source.start(context.currentTime)
    } catch {
      source?.disconnect()
      gain?.disconnect()
      this.musicPlayback = null
    }
  }

  stopMusic(): void {
    this.musicRequested = false
    const playback = this.musicPlayback
    const context = this.context
    this.musicPlayback = null
    if (!playback || !context) return

    const now = context.currentTime
    try {
      playback.gain.gain.cancelScheduledValues(now)
      playback.gain.gain.setValueAtTime(
        Math.max(0.0001, playback.gain.gain.value),
        now,
      )
      playback.gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.18)
      playback.source.stop(now + 0.2)
    } catch {
      playback.source.disconnect()
      playback.gain.disconnect()
    }
  }
}

export const audioEngine = new AudioEngine()
