import {
  DEFAULT_LOADOUT,
  EMPTY_PERMANENT_STAT_LEVELS,
  PLAYER_STAT_CAPS,
  RUNE_IDS,
  UPGRADE_IDS,
  FINAL_CHAMBER,
  applyUpgrade,
  createEndlessCycle,
  createRun,
  deriveLoadoutStats,
  derivePermanentStatProfile,
  SHRINE_HEAL_FRACTION,
  getActiveSynergy,
  getFamilyCounts,
  getRoomNode,
  getRouteChoices,
  getRuneFamily,
  getUpgrade,
  type DifficultyRank,
  type EquipmentLoadout,
  type GameMode,
  type GeneratedRun,
  type PermanentStatProfile,
  type PlayerStatCaps,
  type PlayerStats,
  type RuneId,
  type RunSynergyId,
  type UpgradeId,
} from '../game'
import { audioEngine } from './audio'
import { resetRuntime, runtime } from './registry'
import { enqueueVfx, resetVfxQueue } from '../scene/vfx/vfxQueue'

export type GamePhase =
  | 'title'
  | 'booting'
  | 'lobby'
  | 'expedition-loading'
  | 'playing'
  | 'paused'
  | 'reward'
  | 'shrine'
  | 'route'
  | 'victory'
  | 'defeat'
  | 'error'

export type RuntimeStats = PlayerStats

export interface ProjectileSpawn {
  id: string
  position: [number, number, number]
  direction: [number, number, number]
  speed: number
  damage: number
  color: string
  radius?: number
  kind?: 'arrow' | 'magic' | 'liberation'
  /** Enemy targeted by a Veil Breaker's gaze-release bolt. */
  targetEnemyId?: string
  /** Telegraph delay during which a support projectile remains at its origin. */
  activationDelayMs?: number
}

export type EffectKind =
  | 'slash'
  | 'hit'
  | 'hurt'
  | 'burst'
  | 'dash'
  | 'telegraph'
  | 'trail'
  | 'death'
  /** Red pigment pulled from a hostile figurine when the gaze freezes it. */
  | 'drain'
  /** Gaze takes hold: a ring closing on the enemy plus a rising light column. */
  | 'seal'
  /** The veil tears: radial shards thrown outward from a white core. */
  | 'shatter'

export interface EffectSpawn {
  id: string
  kind: EffectKind
  position: [number, number, number]
  direction?: [number, number, number]
  color: string
  durationMs?: number
  length?: number
  width?: number
  variant?: 'arc' | 'lane' | 'rune' | 'sigil' | 'drain'
  label?: string
}

export interface ThreatWarning {
  id: string
  angleDeg: number
  kind: 'melee' | 'ranged' | 'boss'
  durationMs: number
}

export interface PlayerHitFeedback {
  id: string
  damage: number
  /** Normalized world-space direction from the player toward the attacker. */
  direction: [number, number, number]
}

export interface ShrineState {
  readonly runeChoices: readonly RuneId[]
  readonly healFraction: number
}

export interface StartGeneratedRunOptions {
  readonly loadout?: EquipmentLoadout
  readonly permanentProfile?: PermanentStatProfile
  /** Used by legacy/debug entry points. Normal expeditions wait for scene warmup. */
  readonly startImmediately?: boolean
}

interface SettingsState {
  masterVolume: number
  visionAssist: number
  reducedMotion: boolean
}

export interface GameState {
  phase: GamePhase
  errorMessage: string | null
  seed: string
  runId: number
  roomIndex: number
  roomIds: string[]
  generatedRun: GeneratedRun | null
  currentNodeId: string | null
  visitedNodeIds: string[]
  availableNodeIds: string[]
  mode: GameMode
  dailyDateKey: string | null
  difficulty: DifficultyRank
  health: number
  score: number
  aliveEnemies: number
  observedEnemies: number
  defeatedEnemies: number
  stats: RuntimeStats
  statCaps: PlayerStatCaps
  permanentProfile: PermanentStatProfile
  loadout: EquipmentLoadout
  selectedRunes: RuneId[]
  activeSynergy: RunSynergyId | null
  /** Legacy alias retained for combat systems and older UI call sites. */
  rewardChoices: RuneId[]
  shrine: ShrineState | null
  shrineUsed: boolean
  projectiles: ProjectileSpawn[]
  effects: EffectSpawn[]
  threats: ThreatWarning[]
  lastPlayerHit: PlayerHitFeedback | null
  settings: SettingsState
  beginBoot: () => void
  enterLobby: () => void
  beginPlaying: () => void
  failLoading: (message: string) => void
  startGeneratedRun: (
    run: GeneratedRun,
    options?: StartGeneratedRunOptions,
  ) => void
  startRun: (
    seed: string,
    roomIds: string[],
    loadout: EquipmentLoadout,
    difficulty?: DifficultyRank,
    permanentProfile?: PermanentStatProfile,
  ) => void
  retryCurrentRoom: () => void
  returnToTitle: () => void
  togglePause: () => void
  setRoomPopulation: (count: number) => void
  adjustObservedEnemies: (delta: number) => void
  defeatEnemy: (score: number) => void
  awardScore: (score: number) => void
  damagePlayer: (
    amount: number,
    sourcePosition?: readonly [number, number, number],
  ) => void
  healPlayer: (amount: number) => void
  showReward: (choices: string[]) => void
  chooseRune: (runeId: string) => void
  /** Legacy alias. New reward UI should call chooseRune. */
  chooseUpgrade: (upgradeId: string) => void
  showShrine: (runeIds: string[], healFraction?: number) => void
  chooseShrine: (choice: RuneId | 'heal') => void
  advanceRoom: () => void
  chooseRoute: (nodeId: string) => void
  spawnProjectile: (projectile: ProjectileSpawn) => void
  removeProjectile: (id: string) => void
  spawnEffect: (effect: EffectSpawn) => void
  setThreat: (threat: ThreatWarning) => void
  clearThreat: (id: string) => void
  setMasterVolume: (value: number) => void
  setVisionAssist: (value: number) => void
  setReducedMotion: (value: boolean) => void
}

/** Recent spawns retained for the debug bridge only; the renderer owns lifetime. */
const RECENT_EFFECT_LIMIT = 24

const DEFAULT_PERMANENT_PROFILE = derivePermanentStatProfile(
  EMPTY_PERMANENT_STAT_LEVELS,
)
const DEFAULT_STATS: RuntimeStats = deriveLoadoutStats(DEFAULT_LOADOUT)

function isUpgradeId(value: string): value is UpgradeId {
  return UPGRADE_IDS.includes(value as UpgradeId)
}

function isRuneId(value: string): value is RuneId {
  return RUNE_IDS.includes(value as RuneId)
}

function nextId(prefix: string): string {
  return `${prefix}-${Math.floor(performance.now())}-${Math.random().toString(36).slice(2, 7)}`
}

function clonePermanentProfile(
  profile: PermanentStatProfile = DEFAULT_PERMANENT_PROFILE,
): PermanentStatProfile {
  return { stats: { ...profile.stats }, caps: { ...profile.caps } }
}

function clearsEncounter() {
  // Pending spawns belong to the encounter that just ended.
  resetVfxQueue()
  return {
    aliveEnemies: 0,
    observedEnemies: 0,
    projectiles: [] as ProjectileSpawn[],
    effects: [] as EffectSpawn[],
    threats: [] as ThreatWarning[],
    lastPlayerHit: null,
  }
}

function respectsSynergyInvariant(
  selectedRunes: readonly RuneId[],
  candidate: RuneId,
): boolean {
  if (selectedRunes.includes(candidate)) return false
  const counts = getFamilyCounts([...selectedRunes, candidate])
  return Object.values(counts).filter((count) => count >= 3).length <= 1
}

// Delegates rather than restating the family-to-synergy mapping, which
// runes.ts already owns as FAMILY_SYNERGIES.
const getActiveSynergyFromSelection = getActiveSynergy

function normalizeRuneChoices(
  requestedChoices: readonly string[],
  selectedRunes: readonly RuneId[],
  limit = 3,
): RuneId[] {
  const offered: RuneId[] = []
  for (const requested of requestedChoices) {
    if (offered.length >= limit || !isRuneId(requested)) continue
    const family = getRuneFamily(requested)
    const candidates = [
      requested,
      ...RUNE_IDS.filter((id) => getRuneFamily(id) === family),
      ...RUNE_IDS,
    ]
    const candidate = candidates.find(
      (id) =>
        !offered.includes(id) && respectsSynergyInvariant(selectedRunes, id),
    )
    if (candidate !== undefined) offered.push(candidate)
  }
  return offered
}

function createShrineChoices(
  runeOrder: readonly string[],
  selectedRunes: readonly RuneId[],
): RuneId[] {
  const validOrder = runeOrder.filter(isRuneId)
  const familySeeds = (['blade', 'gaze', 'dodge'] as const).flatMap(
    (family) => {
      const candidate = validOrder.find((id) => getRuneFamily(id) === family)
      return candidate === undefined ? [] : [candidate]
    },
  )
  return normalizeRuneChoices([...familySeeds, ...validOrder], selectedRunes, 3)
}

function prepareRunStats(
  loadout: EquipmentLoadout,
  permanentProfile: PermanentStatProfile,
): RuntimeStats {
  // Deliberate ordering: base -> permanent profile -> equipped items. Runes are
  // applied by chooseRune afterwards with these permanently raised caps.
  return deriveLoadoutStats(
    loadout,
    permanentProfile.stats,
    permanentProfile.caps,
  )
}

function resetPlayerToRoomSpawn(): void {
  runtime.playerPosition.set(0, 0.8, 5.5)
  runtime.enemies.clear()
  runtime.playerInvulnerableUntil = runtime.elapsed
}

export const useGameStore = create<GameState>((set, get) => ({
  phase: 'title',
  errorMessage: null,
  seed: '',
  runId: 0,
  roomIndex: 0,
  roomIds: [],
  generatedRun: null,
  currentNodeId: null,
  visitedNodeIds: [],
  availableNodeIds: [],
  mode: 'standard',
  dailyDateKey: null,
  difficulty: 1,
  health: DEFAULT_STATS.maxHealth,
  score: 0,
  aliveEnemies: 0,
  observedEnemies: 0,
  defeatedEnemies: 0,
  stats: DEFAULT_STATS,
  statCaps: { ...PLAYER_STAT_CAPS },
  permanentProfile: clonePermanentProfile(),
  loadout: { ...DEFAULT_LOADOUT },
  selectedRunes: [],
  activeSynergy: null,
  rewardChoices: [],
  shrine: null,
  shrineUsed: false,
  projectiles: [],
  effects: [],
  threats: [],
  lastPlayerHit: null,
  settings: {
    masterVolume: 0.55,
    visionAssist: 0.75,
    reducedMotion: false,
  },
  beginBoot: () => {
    const phase = get().phase
    if (phase === 'title' || phase === 'lobby' || phase === 'error') {
      set({ phase: 'booting', errorMessage: null })
    }
  },
  enterLobby: () => {
    audioEngine.stopMusic()
    resetRuntime()
    set({
      phase: 'lobby',
      errorMessage: null,
      generatedRun: null,
      currentNodeId: null,
      visitedNodeIds: [],
      availableNodeIds: [],
      roomIndex: 0,
      roomIds: [],
      mode: 'standard',
      dailyDateKey: null,
      rewardChoices: [],
      shrine: null,
      ...clearsEncounter(),
    })
  },
  beginPlaying: () => {
    if (get().phase === 'expedition-loading') set({ phase: 'playing' })
  },
  failLoading: (message) => {
    audioEngine.stopMusic()
    set({
      phase: 'error',
      errorMessage: message.trim() || 'BODA failed to load.',
    })
  },
  startGeneratedRun: (run, options = {}) => {
    const permanentProfile = clonePermanentProfile(options.permanentProfile)
    const loadout = { ...(options.loadout ?? DEFAULT_LOADOUT) }
    const initialStats = prepareRunStats(loadout, permanentProfile)
    const startNode = getRoomNode(run, run.startNodeId)
    audioEngine.startMusic()
    resetRuntime()
    set((state) => ({
      phase: options.startImmediately ? 'playing' : 'expedition-loading',
      errorMessage: null,
      seed: run.seed,
      runId: state.runId + 1,
      roomIndex: startNode.depth - 1,
      roomIds: run.rooms.map((room) => room.templateId),
      generatedRun: run,
      currentNodeId: run.startNodeId,
      visitedNodeIds: [run.startNodeId],
      availableNodeIds: [],
      mode: run.mode,
      dailyDateKey: run.dailyDateKey,
      difficulty: run.difficulty,
      health: initialStats.maxHealth,
      score: 0,
      defeatedEnemies: 0,
      stats: initialStats,
      statCaps: { ...permanentProfile.caps },
      permanentProfile,
      loadout,
      selectedRunes: [],
      activeSynergy: null,
      rewardChoices: [],
      shrine: null,
      shrineUsed: false,
      ...clearsEncounter(),
    }))
  },
  startRun: (seed, roomIds, loadout, difficulty = 1, permanentProfile) => {
    const run = createRun(seed, difficulty)
    get().startGeneratedRun(run, {
      loadout,
      permanentProfile,
      startImmediately: true,
    })
    // Preserve the caller-provided legacy list even though graph navigation is
    // now driven by generatedRun/currentNodeId.
    set({ roomIds: [...roomIds] })
  },
  retryCurrentRoom: () => {
    const state = get()
    if (state.phase !== 'defeat' || state.currentNodeId === null) return
    audioEngine.startMusic()
    resetRuntime()
    resetPlayerToRoomSpawn()
    set({
      phase: 'playing',
      runId: state.runId + 1,
      health: state.stats.maxHealth,
      score: 0,
      defeatedEnemies: 0,
      rewardChoices: [],
      shrine: null,
      ...clearsEncounter(),
    })
  },
  returnToTitle: () => {
    audioEngine.stopMusic()
    resetRuntime()
    set({
      phase: 'title',
      errorMessage: null,
      roomIndex: 0,
      roomIds: [],
      generatedRun: null,
      currentNodeId: null,
      visitedNodeIds: [],
      availableNodeIds: [],
      mode: 'standard',
      dailyDateKey: null,
      selectedRunes: [],
      activeSynergy: null,
      rewardChoices: [],
      shrine: null,
      shrineUsed: false,
      ...clearsEncounter(),
    })
  },
  togglePause: () => {
    const state = get()
    if (state.phase === 'playing') {
      set({ phase: 'paused' })
    } else if (state.phase === 'paused') {
      set({ phase: 'playing' })
    }
  },
  setRoomPopulation: (count) =>
    set({ aliveEnemies: Math.max(0, Math.floor(count)) }),
  adjustObservedEnemies: (delta) =>
    set((state) => ({
      observedEnemies: Math.max(0, state.observedEnemies + delta),
    })),
  defeatEnemy: (enemyScore) => {
    const state = get()
    const remaining = Math.max(0, state.aliveEnemies - 1)
    set({
      aliveEnemies: remaining,
      defeatedEnemies: state.defeatedEnemies + 1,
      score: state.score + enemyScore,
    })
  },
  awardScore: (bonus) => {
    if (!Number.isFinite(bonus) || bonus <= 0) return
    set((state) => ({ score: state.score + Math.floor(bonus) }))
  },
  damagePlayer: (amount, sourcePosition) => {
    const state = get()
    if (
      state.phase !== 'playing' ||
      runtime.elapsed < runtime.playerInvulnerableUntil
    )
      return
    const appliedDamage = Math.max(0, Math.min(state.health, amount))
    if (appliedDamage <= 0) return
    const health = state.health - appliedDamage
    const hitDirection = sourcePosition
      ? runtime.playerHitDirection.set(
          sourcePosition[0] - runtime.playerPosition.x,
          0,
          sourcePosition[2] - runtime.playerPosition.z,
        )
      : runtime.playerHitDirection.copy(runtime.playerFacing).negate().setY(0)
    if (hitDirection.lengthSq() < 0.0001) hitDirection.set(0, 0, 1)
    hitDirection.normalize()
    const direction: [number, number, number] = [
      hitDirection.x,
      0,
      hitDirection.z,
    ]
    const hitId = nextId('player-hit')
    runtime.playerInvulnerableUntil = Math.max(
      runtime.playerInvulnerableUntil,
      runtime.elapsed + 0.25,
    )
    runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.92)
    runtime.cameraKick = Math.max(runtime.cameraKick, 1)
    audioEngine.playDirectional('hurt', Math.max(-1, Math.min(1, direction[0])))
    if (health === 0) audioEngine.stopMusic()
    set({
      health,
      phase: health === 0 ? 'defeat' : state.phase,
      lastPlayerHit: { id: hitId, damage: appliedDamage, direction },
      effects: [
        ...state.effects,
        {
          id: `${hitId}-effect`,
          kind: 'hurt',
          position: [runtime.playerPosition.x, 0.82, runtime.playerPosition.z],
          direction,
          color: '#ff3d57',
          durationMs: 260,
          length: 1.35,
          width: 1.1,
        },
      ],
    })
  },
  healPlayer: (amount) =>
    set((state) => ({
      health: Math.min(
        state.stats.maxHealth,
        state.health + Math.max(0, amount),
      ),
    })),
  showReward: (choices) => {
    const state = get()
    if (state.phase !== 'playing') return
    const rewardChoices = normalizeRuneChoices(choices, state.selectedRunes)
    if (rewardChoices.length === 0) {
      state.advanceRoom()
      return
    }
    audioEngine.play('reward')
    set({ phase: 'reward', rewardChoices, shrine: null })
  },
  chooseRune: (runeId) => {
    const state = get()
    if (
      state.phase !== 'reward' ||
      !isRuneId(runeId) ||
      !state.rewardChoices.includes(runeId) ||
      !respectsSynergyInvariant(state.selectedRunes, runeId)
    ) {
      return
    }
    const stats = applyUpgrade(state.stats, getUpgrade(runeId), state.statCaps)
    const selectedRunes = [...state.selectedRunes, runeId]
    set({
      stats,
      selectedRunes,
      activeSynergy: getActiveSynergyFromSelection(selectedRunes),
      rewardChoices: [],
    })
    get().advanceRoom()
  },
  chooseUpgrade: (upgradeId) => {
    if (!isUpgradeId(upgradeId)) return
    const state = get()
    if (isRuneId(upgradeId)) {
      if (state.phase === 'reward') {
        state.chooseRune(upgradeId)
        return
      }
      if (state.phase === 'shrine') {
        state.chooseShrine(upgradeId)
        return
      }
      if (!respectsSynergyInvariant(state.selectedRunes, upgradeId)) return
    }
    const stats = applyUpgrade(
      state.stats,
      getUpgrade(upgradeId),
      state.statCaps,
    )
    const maxHealthGain = Math.max(0, stats.maxHealth - state.stats.maxHealth)
    const selectedRunes = isRuneId(upgradeId)
      ? [...state.selectedRunes, upgradeId]
      : state.selectedRunes
    set({
      stats,
      health: Math.min(stats.maxHealth, state.health + maxHealthGain),
      selectedRunes,
      activeSynergy: getActiveSynergyFromSelection(selectedRunes),
      rewardChoices: [],
    })
    get().advanceRoom()
  },
  showShrine: (runeIds, healFraction = SHRINE_HEAL_FRACTION) => {
    const state = get()
    if (state.phase !== 'playing') return
    if (state.shrineUsed) {
      state.advanceRoom()
      return
    }
    const runeChoices = createShrineChoices(runeIds, state.selectedRunes)
    audioEngine.play('reward')
    set({
      phase: 'shrine',
      rewardChoices: runeChoices,
      shrine: {
        runeChoices,
        healFraction: Math.max(0, Math.min(1, healFraction)),
      },
    })
  },
  chooseShrine: (choice) => {
    const state = get()
    if (state.phase !== 'shrine' || state.shrine === null) return
    if (choice === 'heal') {
      if (state.health >= state.stats.maxHealth) return
      set({
        health: Math.min(
          state.stats.maxHealth,
          state.health +
            Math.ceil(state.stats.maxHealth * state.shrine.healFraction),
        ),
        shrine: null,
        shrineUsed: true,
        rewardChoices: [],
      })
      get().advanceRoom()
      return
    }
    if (
      !state.shrine.runeChoices.includes(choice) ||
      !respectsSynergyInvariant(state.selectedRunes, choice)
    ) {
      return
    }
    const stats = applyUpgrade(state.stats, getUpgrade(choice), state.statCaps)
    const selectedRunes = [...state.selectedRunes, choice]
    set({
      stats,
      selectedRunes,
      activeSynergy: getActiveSynergyFromSelection(selectedRunes),
      shrine: null,
      shrineUsed: true,
      rewardChoices: [],
    })
    get().advanceRoom()
  },
  advanceRoom: () => {
    const state = get()
    const run = state.generatedRun
    const nodeId = state.currentNodeId
    if (run === null || nodeId === null) {
      const nextRoom = state.roomIndex + 1
      if (nextRoom >= state.roomIds.length) {
        audioEngine.stopMusic()
        audioEngine.play('victory')
        set({ phase: 'victory', projectiles: [], threats: [] })
        return
      }
      resetPlayerToRoomSpawn()
      set({
        phase: 'playing',
        roomIndex: nextRoom,
        rewardChoices: [],
        shrine: null,
        ...clearsEncounter(),
      })
      return
    }

    const currentNode = getRoomNode(run, nodeId)
    if (currentNode.kind === 'boss' || currentNode.nextNodeIds.length === 0) {
      if (state.mode === 'endless') {
        const nextCycleIndex = Math.floor(currentNode.depth / FINAL_CHAMBER)
        const nextRun = createEndlessCycle(
          run.seed,
          state.difficulty,
          nextCycleIndex,
          { routeMapUnlocked: run.routeMapUnlocked },
        )
        const nextStart = getRoomNode(nextRun, nextRun.startNodeId)
        resetPlayerToRoomSpawn()
        set({
          phase: 'expedition-loading',
          runId: state.runId + 1,
          roomIndex: nextStart.depth - 1,
          roomIds: nextRun.rooms.map((room) => room.templateId),
          generatedRun: nextRun,
          currentNodeId: nextRun.startNodeId,
          visitedNodeIds: [nextRun.startNodeId],
          availableNodeIds: [],
          rewardChoices: [],
          shrine: null,
          shrineUsed: false,
          ...clearsEncounter(),
        })
        return
      }
      audioEngine.stopMusic()
      audioEngine.play('victory')
      set({
        phase: 'victory',
        availableNodeIds: [],
        rewardChoices: [],
        shrine: null,
        projectiles: [],
        threats: [],
      })
      return
    }

    const choices = getRouteChoices(run, nodeId)
    if (choices.length > 1) {
      set({
        phase: 'route',
        availableNodeIds: choices.map((choice) => choice.id),
        rewardChoices: [],
        shrine: null,
        projectiles: [],
        threats: [],
      })
      return
    }
    const nextNode = choices[0]
    if (nextNode === undefined) {
      audioEngine.stopMusic()
      audioEngine.play('victory')
      set({ phase: 'victory', projectiles: [], threats: [] })
      return
    }
    resetPlayerToRoomSpawn()
    set({
      phase: 'playing',
      roomIndex: nextNode.depth - 1,
      currentNodeId: nextNode.id,
      visitedNodeIds: [...state.visitedNodeIds, nextNode.id],
      availableNodeIds: [],
      rewardChoices: [],
      shrine: null,
      ...clearsEncounter(),
    })
  },
  chooseRoute: (nodeId) => {
    const state = get()
    if (
      state.phase !== 'route' ||
      state.generatedRun === null ||
      !state.availableNodeIds.includes(nodeId)
    ) {
      return
    }
    const currentNode = state.currentNodeId
      ? getRoomNode(state.generatedRun, state.currentNodeId)
      : null
    const node = getRoomNode(state.generatedRun, nodeId)
    const changingBiome =
      currentNode !== null && currentNode.biomeId !== node.biomeId
    resetPlayerToRoomSpawn()
    set({
      phase: changingBiome ? 'expedition-loading' : 'playing',
      roomIndex: node.depth - 1,
      currentNodeId: node.id,
      visitedNodeIds: [...state.visitedNodeIds, node.id],
      availableNodeIds: [],
      ...clearsEncounter(),
    })
  },
  spawnProjectile: (projectile) =>
    set((state) => ({ projectiles: [...state.projectiles, projectile] })),
  removeProjectile: (id) =>
    set((state) => ({
      projectiles: state.projectiles.filter((item) => item.id !== id),
    })),
  // Spawning is an event handed to the particle renderer, not state the store
  // holds for the effect's lifetime. `effects` is now a bounded ring of recent
  // spawns kept purely so the debug bridge can report what fired; the renderer
  // owns lifetime, so nothing writes to the store when an effect ends.
  spawnEffect: (effect) => {
    const spawned = { ...effect, id: effect.id || nextId('fx') }
    enqueueVfx(spawned)
    set((state) => ({
      effects: [...state.effects, spawned].slice(-RECENT_EFFECT_LIMIT),
    }))
  },
  setThreat: (threat) =>
    set((state) => ({
      threats: [
        ...state.threats.filter((item) => item.id !== threat.id),
        threat,
      ],
    })),
  clearThreat: (id) =>
    set((state) => ({
      threats: state.threats.filter((item) => item.id !== id),
    })),
  setMasterVolume: (value) => {
    audioEngine.setVolume(value)
    set((state) => ({ settings: { ...state.settings, masterVolume: value } }))
  },
  setVisionAssist: (value) =>
    set((state) => ({ settings: { ...state.settings, visionAssist: value } })),
  setReducedMotion: (value) =>
    set((state) => ({ settings: { ...state.settings, reducedMotion: value } })),
}))

export function makeRuntimeId(prefix: string): string {
  return nextId(prefix)
}
