export const BOSS_ARCHETYPES = [
  BOSS_ARCHETYPE,
  MOONBRIAR_QUEEN_ARCHETYPE,
] as const satisfies readonly BossArchetype[]

export function getBossArchetype(id: BossArchetype['id']): BossArchetype {
  const archetype = BOSS_ARCHETYPES.find((candidate) => candidate.id === id)
  if (archetype === undefined) throw new RangeError(`Unknown boss: ${id}`)
  return archetype
}

const STANDARD_OBSERVATION_PROFILE = Object.freeze({
  mode: 'freeze',
} as const satisfies ObservationProfile)

const IMMUNE_OBSERVATION_PROFILE = Object.freeze({
  mode: 'immune',
} as const satisfies ObservationProfile)

const INVERSE_OBSERVATION_PROFILE = Object.freeze({
  mode: 'inverse-freeze',
} as const satisfies ObservationProfile)

/** Returns the gaze rule used by an archetype at a specific seal rank. */
export function getArchetypeObservationProfile(
  archetypeId: CombatantArchetypeId,
  difficulty: DifficultyRank = 1,
): ObservationProfile {
  const rank = getDifficultyRankDefinition(difficulty)
  if (archetypeId === 'gaze-stalker') {
    return INVERSE_OBSERVATION_PROFILE
  }
  if (archetypeId === 'blind-thrall' || archetypeId === 'veil-breaker') {
    return IMMUNE_OBSERVATION_PROFILE
  }
  if (archetypeId === 'moonbriar-queen') {
    return {
      mode: 'break-after',
      breakAfterMs: rank.queenBreakAfterMs,
      rearmHiddenMs: rank.wardenRearmHiddenMs,
    }
  }
  if (archetypeId === 'grave-warden') {
    return {
      mode: 'break-after',
      breakAfterMs: rank.wardenBreakAfterMs,
      rearmHiddenMs: rank.wardenRearmHiddenMs,
    }
  }
  return STANDARD_OBSERVATION_PROFILE
}
