import { createRandomStream } from './rng'
import type {
  ChamberLevel,
  RuneId,
  RunSeed,
  RunSynergyId,
  UpgradeFamily,
  UpgradeId,
} from './types'
import { RUNE_DEFINITIONS } from './upgrades'

export const RUNE_REWARD_CHAMBERS = [
  1, 3, 6, 9,
] as const satisfies readonly ChamberLevel[]

export const FAMILY_SYNERGIES: Readonly<Record<UpgradeFamily, RunSynergyId>> =
  Object.freeze({
    blade: 'triple-cut',
    gaze: 'undying-eye',
    dodge: 'afterimage-burst',
  })

/** Fraction of maximum health the chamber-five shrine restores. */
export const SHRINE_HEAL_FRACTION = 0.35

export type RuneOffering = readonly [RuneId, RuneId, RuneId]
export type RuneOfferingSchedule = Readonly<
  Record<(typeof RUNE_REWARD_CHAMBERS)[number], RuneOffering>
>

const runesByFamily = Object.freeze({
  blade: RUNE_DEFINITIONS.filter((rune) => rune.family === 'blade').map(
    (rune) => rune.id,
  ),
  gaze: RUNE_DEFINITIONS.filter((rune) => rune.family === 'gaze').map(
    (rune) => rune.id,
  ),
  dodge: RUNE_DEFINITIONS.filter((rune) => rune.family === 'dodge').map(
    (rune) => rune.id,
  ),
} satisfies Readonly<Record<UpgradeFamily, readonly RuneId[]>>)

export function getRuneFamily(id: RuneId): UpgradeFamily {
  const rune = RUNE_DEFINITIONS.find((definition) => definition.id === id)
  if (rune === undefined) throw new RangeError(`Unknown rune: ${id}`)
  return rune.family
}

export function getRunesInFamily(family: UpgradeFamily): readonly RuneId[] {
  return runesByFamily[family]
}

/**
 * Produces four offers with exactly one rune from each family. Each family's
 * four runes are exhausted once, making offerings stable and duplicate-free.
 */
export function createRuneOfferingSchedule(
  seed: RunSeed,
): RuneOfferingSchedule {
  const orders = {
    blade: createRandomStream(seed, 'runes:blade').shuffle(runesByFamily.blade),
    gaze: createRandomStream(seed, 'runes:gaze').shuffle(runesByFamily.gaze),
    dodge: createRandomStream(seed, 'runes:dodge').shuffle(runesByFamily.dodge),
  }

  const schedule = {} as Record<number, RuneOffering>
  RUNE_REWARD_CHAMBERS.forEach((chamber, index) => {
    schedule[chamber] = [
      orders.blade[index] as RuneId,
      orders.gaze[index] as RuneId,
      orders.dodge[index] as RuneId,
    ]
  })
  return schedule as RuneOfferingSchedule
}

export function getDeterministicRuneOfferings(
  seed: RunSeed,
  chamber: (typeof RUNE_REWARD_CHAMBERS)[number],
): RuneOffering {
  return createRuneOfferingSchedule(seed)[chamber]
}

export function createShrineRuneOrder(seed: RunSeed): readonly RuneId[] {
  return createRandomStream(seed, 'runes:shrine').shuffle(
    RUNE_DEFINITIONS.map((rune) => rune.id),
  )
}

export function resolveShrineRuneChoice(
  runeOrder: readonly RuneId[],
  ownedRuneIds: readonly UpgradeId[],
): RuneId | null {
  const owned = new Set(ownedRuneIds)
  return runeOrder.find((id) => !owned.has(id)) ?? null
}

export function getFamilyCounts(
  runeIds: readonly UpgradeId[],
): Readonly<Record<UpgradeFamily, number>> {
  const unique = new Set(runeIds)
  return {
    blade: runesByFamily.blade.filter((id) => unique.has(id)).length,
    gaze: runesByFamily.gaze.filter((id) => unique.has(id)).length,
    dodge: runesByFamily.dodge.filter((id) => unique.has(id)).length,
  }
}

export function getActiveSynergies(
  runeIds: readonly UpgradeId[],
): readonly RunSynergyId[] {
  const counts: Record<UpgradeFamily, number> = { blade: 0, gaze: 0, dodge: 0 }
  const seen = new Set<UpgradeId>()
  for (const id of runeIds) {
    if (seen.has(id)) continue
    seen.add(id)
    const definition = RUNE_DEFINITIONS.find((rune) => rune.id === id)
    if (definition === undefined) continue
    counts[definition.family] += 1
    if (counts[definition.family] === 3) {
      return [FAMILY_SYNERGIES[definition.family]]
    }
  }
  return []
}

export function getActiveSynergy(
  runeIds: readonly UpgradeId[],
): RunSynergyId | null {
  return getActiveSynergies(runeIds)[0] ?? null
}

export interface RuneAttackContext {
  readonly baseDamage: number
  readonly runeIds: readonly UpgradeId[]
  readonly targetHealthRatio: number
  readonly targetObserved: boolean
  /**
   * Gaze time retained by the target's Undying Eye mark. Once marked, this
   * remains at or above the activation threshold during its hidden grace.
   */
  readonly continuousObservedMs: number
  readonly timeSinceDodgeEndMs: number | null
  /** Number of prior successful melee attacks in the current triple-cut cycle. */
  readonly successfulMeleeHitCount: number
}

export interface RuneAttackResolution {
  readonly damage: number
  readonly multiplier: number
  readonly nextSuccessfulMeleeHitCount: number
  readonly consumesCounterStep: boolean
  readonly applied: readonly string[]
}

export function resolveRuneAttack(
  context: RuneAttackContext,
): RuneAttackResolution {
  const owned = new Set(context.runeIds)
  const synergies = new Set(getActiveSynergies(context.runeIds))
  const applied: string[] = []
  let multiplier = 1

  if (owned.has('execution-mark') && context.targetHealthRatio <= 0.3) {
    multiplier *= 1.3
    applied.push('execution-mark')
  }
  if (owned.has('watcher-pressure') && context.targetObserved) {
    multiplier *= 1.15
    applied.push('watcher-pressure')
  }
  if (
    synergies.has('undying-eye') &&
    context.continuousObservedMs >= UNDYING_EYE_MARK_AFTER_MS
  ) {
    multiplier *= UNDYING_EYE_DAMAGE_MULTIPLIER
    applied.push('undying-eye')
  }

  const consumesCounterStep =
    owned.has('counter-step') &&
    context.timeSinceDodgeEndMs !== null &&
    context.timeSinceDodgeEndMs >= 0 &&
    context.timeSinceDodgeEndMs <= 1_000
  if (consumesCounterStep) {
    multiplier *= 1.25
    applied.push('counter-step')
  }

  const nextHitCount = Math.max(0, context.successfulMeleeHitCount) + 1
  const tripleCut = synergies.has('triple-cut') && nextHitCount >= 3
  if (tripleCut) {
    multiplier *= 1.5
    applied.push('triple-cut')
  }

  return {
    damage: Math.max(0, context.baseDamage) * multiplier,
    multiplier,
    nextSuccessfulMeleeHitCount: tripleCut ? 0 : nextHitCount,
    consumesCounterStep,
    applied,
  }
}

export interface VisionRuneRules {
  readonly exitGraceMs: number
  readonly breakAfterMultiplier: number
}

export function resolveVisionRuneRules(
  runeIds: readonly UpgradeId[],
  baseExitGraceMs = 100,
): VisionRuneRules {
  const owned = new Set(runeIds)
  return {
    exitGraceMs: Math.max(
      0,
      baseExitGraceMs + (owned.has('lingering-gaze') ? 150 : 0),
    ),
    breakAfterMultiplier: owned.has('veil-anchor') ? 1.25 : 1,
  }
}

export interface DodgeRuneRules {
  readonly invulnerabilityDurationMs: number
  readonly afterimageRadius: number
  readonly afterimageDamage: number
}

export function resolveDodgeRuneRules(
  runeIds: readonly UpgradeId[],
  currentAttackDamage = 0,
): DodgeRuneRules {
  const owned = new Set(runeIds)
  const hasAfterimage = getActiveSynergies(runeIds).includes('afterimage-burst')
  return {
    invulnerabilityDurationMs: owned.has('ghost-skin') ? 250 : 0,
    afterimageRadius: hasAfterimage ? 1.8 : 0,
    afterimageDamage: hasAfterimage
      ? Math.max(0, currentAttackDamage) * 0.65
      : 0,
  }
}

export function resolveAfterimageHit(
  runeIds: readonly UpgradeId[],
  distance: number,
  alreadyHit: boolean,
  currentAttackDamage: number,
): number {
  if (alreadyHit || !Number.isFinite(distance) || distance < 0) return 0
  const rules = resolveDodgeRuneRules(runeIds, currentAttackDamage)
  return distance <= rules.afterimageRadius ? rules.afterimageDamage : 0
}

export interface UndyingEyeState {
  readonly marked: boolean
  readonly observedMs: number
  readonly hiddenMs: number
}

export const UNDYING_EYE_MARK_AFTER_MS = 750
export const UNDYING_EYE_HIDDEN_GRACE_MS = 1_500
export const UNDYING_EYE_DAMAGE_MULTIPLIER = 1.25

export const INITIAL_UNDYING_EYE_STATE: UndyingEyeState = Object.freeze({
  marked: false,
  observedMs: 0,
  hiddenMs: 0,
})

export function updateUndyingEyeState(
  previous: UndyingEyeState,
  observed: boolean,
  deltaMs: number,
): UndyingEyeState {
  if (!Number.isFinite(deltaMs) || deltaMs < 0) {
    throw new RangeError('deltaMs must be a non-negative finite number')
  }
  if (observed) {
    const observedMs = previous.observedMs + deltaMs
    return {
      marked: previous.marked || observedMs >= UNDYING_EYE_MARK_AFTER_MS,
      observedMs,
      hiddenMs: 0,
    }
  }

  // The activation requirement is continuous gaze. Only a completed mark
  // survives leaving the field of view.
  if (!previous.marked) return INITIAL_UNDYING_EYE_STATE

  const hiddenMs = previous.hiddenMs + deltaMs
  if (hiddenMs >= UNDYING_EYE_HIDDEN_GRACE_MS) {
    return INITIAL_UNDYING_EYE_STATE
  }
  return { ...previous, hiddenMs }
}

export function calculateShrineHealthAfterHeal(
  currentHealth: number,
  maxHealth: number,
): number {
  if (!Number.isFinite(currentHealth) || !Number.isFinite(maxHealth)) {
    throw new RangeError('Shrine health values must be finite')
  }
  const safeMax = Math.max(1, maxHealth)
  return Math.min(
    safeMax,
    Math.max(0, currentHealth) + Math.ceil(safeMax * SHRINE_HEAL_FRACTION),
  )
}
